def find_products(vars):
    p = vars.get('products')
    if isinstance(p, str):
        try:
            p = json.loads(p)
        except Exception:
            try:
                p = json.loads(p.replace("'", '"'))
            except Exception:
                p = None
    if isinstance(p, dict):
        p = [p[k] for k in sorted(p)]
    if isinstance(p, list) and p and isinstance(p[0], dict):
        return p
    out = {}
    for k in list(vars.keys()):
        if '.data.products.' in str(k):
            rest = str(k).split('.data.products.')[1].split('.')
            if len(rest) == 2:
                out.setdefault(rest[0], {})[rest[1]] = vars.get(k)
    return [out[k] for k in sorted(out)]
try:
    now = get_now(vars)
    today = now.date()
    prods = find_products(vars)[:3]
    fri = today
    while not is_bd(fri) or (fri + datetime.timedelta(days=1)).weekday() < 5 and is_bd(fri + datetime.timedelta(days=1)):
        fri = fri + datetime.timedelta(days=1)
        if fri.weekday() >= 5:
            break
    wk = [today + datetime.timedelta(days=i - today.weekday()) for i in range(5)]
