    last_this = wk[-1] if wk else None
    if last_this is None or last_this == today:
        mon = today + datetime.timedelta(days=7 - today.weekday())
        nw = [d for d in [mon + datetime.timedelta(days=i) for i in range(5)] if is_bd(d)]
        a1 = nw[-1]
    else:
        a1 = last_this
    pf = {}
    lines = []
    maxdl = today
    names = {'credit_card': 'credit card', 'personal_loan': 'personal loan', 'car_loan': 'car loan'}
    for i, p in enumerate(prods):
        pid = str(p.get('product_id'))
        late = int(float(p.get('days_late') or 0))
        full = round(float(p.get('past_due') or 0), 2)
        ty = str(p.get('type'))
        label = names.get(ty, ty)
        if ty == 'credit_card':
            label = 'credit card ending ' + str(p.get('card_last4'))
            floor = round(float(p.get('minimum_payment') or full), 2)
        else:
            floor = round(float(p.get('instalment_amount') or full), 2)
        early = late <= 7
        dl = add_bd(today, 12 if early else 7)
        if dl > maxdl:
            maxdl = dl
        att = 1 if early else 2
        a1d = a1 if a1 <= dl else dl
        bdays = []
        d = today
        while d <= dl:
            if is_bd(d):
                bdays.append(d.isoformat())
            d = d + datetime.timedelta(days=1)
        pf[pid] = dict(floor=floor, full=full, deadline=dl.isoformat(), today=today.isoformat(), bdays=bdays, label=label, n=i + 1)
        s = 'Product %d: product_id %s; name it as "%s"; past due %.2f; %d days late; lowest amount that can be recorded %.2f; latest date that can be recorded (deadline) %s; persuasion attempts allowed for this product: %d; attempt 1 = the full past-due amount (or %.2f if the customer already said the full amount is too much) on %s' % (i + 1, pid, label, full, late, floor, say(dl), att, floor, say(a1d))
        s += ('; attempt 2 = %.2f on the deadline %s.' % (floor, say(dl))) if att == 2 else '; there is no attempt 2 for this product.'
        lines.append(s)
        vars['p%d_id' % (i + 1)] = pid
    cal = []
    d = today
    while d <= maxdl:
        cal.append(d.strftime('%a %d %b') + ('' if is_bd(d) else ' (NOT a business day' + (', bank holiday' if d.isoformat() in H else '') + ')'))
        d = d + datetime.timedelta(days=1)
    vars['facts'] = 'Today is ' + say(today) + '.\n' + '\n'.join(lines) + '\nCalendar from today to the last deadline: ' + ', '.join(cal) + '.\n"This <weekday>" is in the current calendar week; "next <weekday>" is that weekday in the following calendar week.'
    vars['pf_json'] = json.dumps(pf)
    vars['n_products'] = len(prods)
    vars['multi'] = 'yes' if len(prods) > 1 else 'no'
    vars['first_ask'] = 'Ask whether the customer can pay all of them today; if not, go through the products one by one in the listed order, without asking about today again, starting each product at its attempt 1.' if len(prods) > 1 else 'Ask exactly: "Can you make this payment today?"'
except Exception as e:
    vars['facts'] = vars.get('facts') or 'Account data could not be prepared.'
    vars['pf_json'] = vars.get('pf_json') or ''
    vars['first_ask'] = 'Ask exactly: "Can you make this payment today?"'
vars['stage'] = 'verified'
vars['outcome'] = 'no_promise'
vars['reason'] = 'refused'

