import datetime, json
H = ['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01']
def is_bd(d, H=H):
    return d.weekday() < 5 and d.isoformat() not in H
def add_bd(d, n, H=H):
    while n > 0:
        d = d + datetime.timedelta(days=1)
        if d.weekday() < 5 and d.isoformat() not in H:
            n -= 1
    return d
def say(d):
    return d.strftime('%A %d %B %Y') + ' (' + d.isoformat() + ')'
def get_now(vars):
    try:
        return datetime.datetime.fromisoformat(str(vars.get('now'))[:16])
    except Exception:
        return datetime.datetime(2026, 10, 14, 11, 0)

try:
    now = get_now(vars)
    today = now.date()
    nb = add_bd(today, 1)
    parts = []
    if is_bd(today) and now.hour < 19:
        parts.append('today ' + say(today) + ' at a time later than ' + now.strftime('%H:%M') + ' and not before 10:00, up to 19:00')
    parts.append('the next business day ' + say(nb) + ' from 10:00 to 19:00, both included')
    vars['cb_facts'] = 'Allowed callback slots: ' + '; or '.join(parts) + '. Nothing else can be booked.'
except Exception:
    vars['cb_facts'] = 'Allowed callback slots: today or the next business day, 10:00 to 19:00, later than now.'
vars['outcome'] = 'not_reached'
vars['reason'] = 'unclear'
vars['stage'] = 'reach'
vars['farewell'] = 'Thank you for your time. Goodbye.'
vars['facts'] = ''
vars['xfer_queue'] = ''
for i in ('1', '2', '3'):
    vars['n' + i + '_id'] = ''
    vars['n' + i + '_reason'] = ''

import json
def g(vars, k):
    return str(vars.get(k) or '').strip().lower()
try:
    bye = 'Thank you for your time. Goodbye.'
    outcome, reason, queue = 'not_reached', 'unclear', ''
    notes = []
    verified = g(vars, 'stage') == 'verified'
    try:
        pf = json.loads(vars.get('pf_json') or '{}')
    except Exception:
        pf = {}
    pids = sorted(pf, key=lambda k: pf[k].get('n', 0))
    rec = [p for p in pids if vars.get('rec_' + p) == 'ok']
    if not rec and pids:
        try:
            ok_n = int(float(vars.get('create_promise_success_count') or 0))
        except Exception:
            ok_n = 0
        if ok_n >= 1 and len(pids) == 1:
            rec = pids[:1]
    if g(vars, 'human') == 'insists':
        outcome, reason, queue = 'transferred', 'human', 'general'
    elif verified and g(vars, 'wrap') == 'restructuring':
        outcome, reason, queue = 'transferred', 'restructuring', 'restructuring'
    elif verified and g(vars, 'hardship') == 'support_accepted':
        outcome, reason, queue = 'transferred', 'support', 'support'
    elif not verified:
        who = g(vars, 'who')
        try:
            cb = int(float(vars.get('schedule_callback_success_count') or 0))
        except Exception:
            cb = 0
        left = g(vars, 'verify_identity_response.data.wrong_answers_left')
        if who == 'deceased':
            reason, bye = 'deceased', 'I am sorry for your loss. Thank you. Goodbye.'
        elif who == 'wrong_number':
            reason = 'wrong_number'
        elif cb >= 1:
            reason = 'callback'
        elif who == 'third_party':
            reason = 'no_callback'
        elif who == 'customer':
            outcome = 'not_verified'
            if left in ('0', '0.0'):
                reason, bye = 'failed', 'I could not verify your identity, so I cannot continue. Please use the Freya Bank mobile app or visit a branch. Thank you for your time. Goodbye.'
            else:
                reason = 'declined'
    else:
        multi = len(pids) > 1
        hard = g(vars, 'hardship') in ('mentioned', 'support_declined')
        why = {}
        for i, p in enumerate(pids):
            if p in rec:
                continue
            s = g(vars, 'p%d_state' % (i + 1))
            try:
                failed = int(vars.get('fail_' + p) or 0) >= 2
            except Exception:
                failed = False
            if not multi and not failed:
                try:
                    failed = int(float(vars.get('create_promise_failure_count') or 0)) - int(vars.get('blocked_n') or 0) >= 2
                except Exception:
                    failed = False
            if failed:
                s = 'service_error'
            elif s not in ('paid', 'dispute', 'hardship', 'refused'):
                s = 'hardship' if hard else 'refused'
            elif s == 'refused' and hard:
                s = 'hardship'
            why[p] = s
        if multi:
            notes = [(p, why[p]) for p in pids if p in why]
        if rec:
            outcome, reason = 'promise', ''
        else:
            rest = [why[p] for p in pids if why.get(p) != 'paid']
            if pids and not rest:
                outcome, reason = 'paid', ''
            else:
                outcome, reason = 'no_promise', (rest[0] if rest else 'refused')
    if queue:
        notes = []
        bye = 'I am transferring you to a colleague now. Thank you for your time. Goodbye.'
    vars['outcome'], vars['reason'], vars['xfer_queue'], vars['farewell'] = outcome, reason, queue, bye
    for i in range(3):
        vars['n%d_id' % (i + 1)] = notes[i][0] if i < len(notes) else ''
        vars['n%d_reason' % (i + 1)] = notes[i][1] if i < len(notes) else ''
except Exception:
    vars['farewell'] = 'Thank you for your time. Goodbye.'

